// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.10;

import {IERC20} from '../../dependencies/openzeppelin/contracts/IERC20.sol';
import {GPv2SafeERC20} from '../../dependencies/gnosis/contracts/GPv2SafeERC20.sol';
import {SafeCast} from '../../dependencies/openzeppelin/contracts/SafeCast.sol';
import {VersionedInitializable} from '../libraries/aave-upgradeability/VersionedInitializable.sol';
import {Errors} from '../libraries/helpers/Errors.sol';
import {WadRayMath} from '../libraries/math/WadRayMath.sol';
import {IPool} from '../../interfaces/IPool.sol';
import {DataTypes} from '../libraries/types/DataTypes.sol';
import {ReserveConfiguration} from '../libraries/configuration/ReserveConfiguration.sol';
import {IAToken} from '../../interfaces/IAToken.sol';
import {IAaveIncentivesController} from '../../interfaces/IAaveIncentivesController.sol';
import {IInitializableAToken} from '../../interfaces/IInitializableAToken.sol';
import {ScaledBalanceTokenBase} from './base/ScaledBalanceTokenBase.sol';
import {IncentivizedERC20} from './base/IncentivizedERC20.sol';
import {EIP712Base} from './base/EIP712Base.sol';

/**
 * @title Aave ERC20 AToken
 * @author Aave
 * @notice Implementation of the interest bearing token for the Aave protocol
 */
contract AToken is VersionedInitializable, ScaledBalanceTokenBase, EIP712Base, IAToken {
  using WadRayMath for uint256;
  using SafeCast for uint256;
  using GPv2SafeERC20 for IERC20;
  using ReserveConfiguration for DataTypes.ReserveConfigurationMap;

  bytes32 public constant PERMIT_TYPEHASH =
    keccak256('Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)');

  uint256 public constant ATOKEN_REVISION = 0x5;

  address internal _treasury;
  address internal _underlyingAsset;

  // ------------------------------------------------------------------------------------------
  // One-shot socialized-loss adjustment (2026-09-09 ctUSD deficit). See applyDeficitAdjustment.
  //
  // Storage: THREE slots appended AFTER _underlyingAsset (slot 61 of the rev-3 layout):
  //   slot 62: _deficitCursor (20 bytes) + _deficitSealed (1 byte), packed
  //   slot 63: _deficitFactorRay
  //   slot 64: _deficitTargetScaled
  // AToken declares no state beyond this point. ZToken and DelegationAwareAToken inherit AToken
  // but add NO storage of their own, and no proxy in this deployment runs either, so all three
  // slots are virgin on every live proxy; an `updateAToken` to this revision cannot collide with
  // anything a proxy already holds. Slots 0-61 are byte-identical to the rev-3 layout (verified
  // with solc `storageLayout` output; see scripts-clean/haircut/README.md).
  //
  // The entry point is bound to ONE reserve (DEFICIT_ASSET). The same implementation is installed
  // on the zUSDC.e and zWcBTC proxies by the #35 rollout; on those, applyDeficitAdjustment always
  // reverts DEFICIT_WRONG_RESERVE and sealDeficitAdjustment closes the dormant entry point for good.
  // ------------------------------------------------------------------------------------------

  /// @dev ctUSD (Citrea mainnet, chainId 4114): the ONLY underlying whose aToken may be adjusted.
  address public constant DEFICIT_ASSET = 0x8D82c4E3c936C7B5724A382a9c5a4E6Eb7aB6d5D;

  /// @dev Highest holder address already adjusted. Batches must arrive in STRICTLY ASCENDING
  ///      address order, which makes double-application impossible across the whole operation
  ///      without a per-holder flag (2,103 flags would cost ~42M gas on their own).
  address internal _deficitCursor;
  /// @dev Once true, both entry points below are permanently dead. The function is one-shot.
  bool internal _deficitSealed;
  /// @dev Surviving fraction of every scaled balance, in ray. Committed by the FIRST batch and
  ///      immutable for the rest of the operation, so every holder is cut by the same ratio.
  uint256 internal _deficitFactorRay;
  /// @dev Completeness bound, stored by the FIRST batch before anything is burned:
  ///      floor(scaledTotalSupply * factorRay / RAY). sealDeficitAdjustment requires the live
  ///      scaledTotalSupply to be AT OR BELOW it (see the proof in sealDeficitAdjustment).
  uint256 internal _deficitTargetScaled;

  /**
   * @dev Emitted once, by the first batch, before any balance changes. `targetScaled` is the value
   *      sealDeficitAdjustment will hold the final scaledTotalSupply to.
   */
  event DeficitAdjustmentStarted(
    uint256 factorRay,
    uint256 scaledTotalSupplyBefore,
    uint256 targetScaled
  );

  /**
   * @dev Emitted once per adjusted holder. The published per-address loss list is exactly the
   *      set of these logs: `scaledBefore - scaledAfter` is that address's burn, in scaled units.
   */
  event DeficitAdjustment(
    address indexed user,
    uint256 scaledBefore,
    uint256 scaledAfter,
    uint256 factorRay
  );

  /// @dev Emitted when the adjustment is sealed; after this the entry points always revert.
  event DeficitAdjustmentSealed(
    uint256 factorRay,
    uint256 scaledTotalSupplyAfter,
    uint256 targetScaled,
    address lastHolder
  );

  /// @inheritdoc VersionedInitializable
  function getRevision() internal pure virtual override returns (uint256) {
    return ATOKEN_REVISION;
  }

  /**
   * @dev Constructor.
   * @param pool The address of the Pool contract
   */
  constructor(
    IPool pool
  ) ScaledBalanceTokenBase(pool, 'ATOKEN_IMPL', 'ATOKEN_IMPL', 0) EIP712Base() {
    // Intentionally left blank
  }

  /// @inheritdoc IInitializableAToken
  function initialize(
    IPool initializingPool,
    address treasury,
    address underlyingAsset,
    IAaveIncentivesController incentivesController,
    uint8 aTokenDecimals,
    string calldata aTokenName,
    string calldata aTokenSymbol,
    bytes calldata params
  ) public virtual override initializer {
    require(initializingPool == POOL, Errors.POOL_ADDRESSES_DO_NOT_MATCH);
    _setName(aTokenName);
    _setSymbol(aTokenSymbol);
    _setDecimals(aTokenDecimals);

    _treasury = treasury;
    _underlyingAsset = underlyingAsset;
    _incentivesController = incentivesController;

    _domainSeparator = _calculateDomainSeparator();

    emit Initialized(
      underlyingAsset,
      address(POOL),
      treasury,
      address(incentivesController),
      aTokenDecimals,
      aTokenName,
      aTokenSymbol,
      params
    );
  }

  /// @inheritdoc IAToken
  function mint(
    address caller,
    address onBehalfOf,
    uint256 amount,
    uint256 index
  ) external virtual override onlyPool returns (bool) {
    return _mintScaled(caller, onBehalfOf, amount, index);
  }

  /// @inheritdoc IAToken
  function burn(
    address from,
    address receiverOfUnderlying,
    uint256 amount,
    uint256 index
  ) external virtual override onlyPool {
    _burnScaled(from, receiverOfUnderlying, amount, index);
    if (receiverOfUnderlying != address(this)) {
      IERC20(_underlyingAsset).safeTransfer(receiverOfUnderlying, amount);
    }
  }

  /// @inheritdoc IAToken
  function mintToTreasury(uint256 amount, uint256 index) external virtual override onlyPool {
    if (amount == 0) {
      return;
    }
    // With floor rounding, a sub-share `amount` scales to 0, which would make
    // `_mintScaled` revert with INVALID_MINT_AMOUNT and could brick Pool flows that
    // mint accrued reserves to the treasury. Skip the dust instead; the `amount == 0`
    // guard above is insufficient once the scaled amount is floored.
    if (amount.rayDivFloor(index) == 0) {
      return;
    }
    _mintScaled(address(POOL), _treasury, amount, index);
  }

  /// @inheritdoc IAToken
  function transferOnLiquidation(
    address from,
    address to,
    uint256 value
  ) external virtual override onlyPool {
    // Being a normal transfer, the Transfer() and BalanceTransfer() are emitted
    // so no need to emit a specific event here
    _transfer(from, to, value, false);
  }

  /// @inheritdoc IERC20
  function balanceOf(
    address user
  ) public view virtual override(IncentivizedERC20, IERC20) returns (uint256) {
    return super.balanceOf(user).rayMulFloor(POOL.getReserveNormalizedIncome(_underlyingAsset));
  }

  /// @inheritdoc IERC20
  function totalSupply() public view virtual override(IncentivizedERC20, IERC20) returns (uint256) {
    uint256 currentSupplyScaled = super.totalSupply();

    if (currentSupplyScaled == 0) {
      return 0;
    }

    return currentSupplyScaled.rayMulFloor(POOL.getReserveNormalizedIncome(_underlyingAsset));
  }

  /// @inheritdoc IAToken
  function RESERVE_TREASURY_ADDRESS() external view override returns (address) {
    return _treasury;
  }

  /// @inheritdoc IAToken
  function UNDERLYING_ASSET_ADDRESS() external view override returns (address) {
    return _underlyingAsset;
  }

  /// @inheritdoc IAToken
  function transferUnderlyingTo(address target, uint256 amount) external virtual override onlyPool {
    IERC20(_underlyingAsset).safeTransfer(target, amount);
  }

  /// @inheritdoc IAToken
  function handleRepayment(
    address user,
    address onBehalfOf,
    uint256 amount
  ) external virtual override onlyPool {
    // Intentionally left blank
  }

  /**
   * @notice ONE-SHOT socialized-loss adjustment: reduces each listed holder's SCALED balance to
   *         `scaled * factorRay / RAY`, burning the difference. ctUSD (DEFICIT_ASSET) only.
   *
   * @dev Why the scaled balance and not the reserve's liquidity index. A uniform cut can also be
   *      expressed by lowering `liquidityIndex` (one word, in the POOL's reserve struct). That
   *      BRICKS the reserve: `ScaledBalanceTokenBase` computes, on every mint / burn / transfer,
   *          balanceIncrease = _balanceFromScaled(scaled, index)
   *                          - _balanceFromScaled(scaled, _userState[user].additionalData)
   *      where `additionalData` is the index at the holder's last interaction. `liquidityIndex`
   *      starts at RAY and only grows, so additionalData >= RAY for every holder, while a ~10%
   *      cut lands the index BELOW RAY — the subtraction underflows and reverts Panic(0x11) for
   *      EVERY holder, on withdraw, transfer, burn and transferOnLiquidation alike. Verified on a
   *      Citrea mainnet fork against the rev-3 (live) and this implementation
   *      (scripts-clean/testing/haircut-index-cut-hazard-fork.ts).
   *      Reducing `scaledBalance` instead leaves `index` untouched, so that subtraction keeps
   *      working; `balanceOf = scaled * index` falls by exactly `1 - factorRay/RAY` for everyone.
   *
   *      Rounding: the SURVIVING balance is floored, so the cut rounds UP, in the reserve's
   *      favour. The sum of per-holder cuts therefore always meets or exceeds the target and the
   *      reserve can never be left short by rounding; the residue is at most one scaled unit per
   *      holder (~2.1e3 scaled units ~= 0.002 ctUSD across the whole 2,104-address book).
   *
   *      Completeness (the seal). The FIRST batch, before it burns anything, stores
   *          _deficitTargetScaled = floor(scaledTotalSupply * factorRay / RAY)
   *      and `sealDeficitAdjustment` requires the live scaledTotalSupply to be <= that value. A
   *      complete run always satisfies it (sum of floors <= floor of the sum); a run that skipped a
   *      holder ends ABOVE it unless that holder's cut is smaller than the aggregate rounding
   *      slack. See `sealDeficitAdjustment` for the bound and what the Timelock payload covers.
   *
   *      Non-holders. Every listed address MUST hold a non-zero scaled balance; a zero-balance
   *      (mistyped or stale) address reverts the WHOLE batch with DEFICIT_NOT_A_HOLDER instead of
   *      silently advancing the cursor past every real holder above it.
   *
   *      Event fidelity. Indexers reconstruct `balanceOf` by summing Transfer events, and this
   *      token books accrued interest into the event stream lazily: the interest a holder earned
   *      since `additionalData` is emitted as a Mint on their NEXT interaction. This function
   *      therefore does exactly what `_burnScaled` does for a debit of `cutUnderlying`: it emits
   *      the accrued `balanceIncrease`, refreshes `additionalData` to the current index and nets
   *      the two (Mint if the accrued interest exceeds the cut, Burn otherwise). Reconciliation
   *      per holder: floor(scaledBefore * previousIndex) + netTransferDelta == balanceOf after.
   *      Leaving `additionalData` alone would make the event stream permanently understate every
   *      cut holder's balance by the interest accrued on the burned portion.
   *
   * @param holders Addresses to adjust, in STRICTLY ASCENDING order, each greater than every
   *        address processed in any previous batch. This ordering is what makes the operation
   *        one-shot: no address can be adjusted twice, in this batch or across batches.
   * @param factorRay The surviving fraction in ray, in (0, RAY). Committed by the first batch;
   *        every later batch must pass the identical value. It is derived OFF CHAIN, from ONE
   *        block, AFTER PR #36 (zero rates: the index is frozen, so the factor cannot go stale
   *        during the 48 h Timelock delay) and AFTER a second `Pool.mintToTreasury([ctUSD])` (so
   *        the treasury's accrued claims are in scaledTotalSupply and take the same cut):
   *            targetScaledTotal = floor(assets * RAY / liquidityIndex)   (assets = cash + debt)
   *            factorRay         = floor(targetScaledTotal * RAY / scaledTotalSupply)
   *        so that claims <= assets afterwards. ILLUSTRATIVE ONLY: at fork block 12,519,900 with
   *        #36 modelled this gives factorRay ~= 0.8982e27, a ~10.18% cut; the production value
   *        is whatever that derivation yields at the real snapshot block and is pinned by the
   *        Timelock operation id together with the holder list.
   * @return scaledBurned Total scaled units burned by this batch.
   */
  function applyDeficitAdjustment(
    address[] calldata holders,
    uint256 factorRay
  ) external virtual onlyPoolAdmin returns (uint256 scaledBurned) {
    require(!_deficitSealed, 'DEFICIT_ADJUSTMENT_SEALED');
    require(_underlyingAsset == DEFICIT_ASSET, 'DEFICIT_WRONG_RESERVE');
    require(factorRay != 0 && factorRay < WadRayMath.RAY, 'INVALID_DEFICIT_FACTOR');
    // The reserve MUST be paused for the whole operation: balances are being rewritten out from
    // under holders, and a live reserve would let anyone withdraw at the pre-cut balance (or be
    // liquidated at it) between batches.
    require(POOL.getConfiguration(_underlyingAsset).getPaused(), 'RESERVE_NOT_PAUSED');
    require(holders.length != 0, 'DEFICIT_EMPTY_BATCH');

    uint256 committed = _deficitFactorRay;
    if (committed == 0) {
      // First batch: commit the factor and the completeness bound BEFORE any balance changes.
      // `super.totalSupply()` is the scaled total supply (IncentivizedERC20).
      uint256 scaledTotalSupplyBefore = super.totalSupply();
      uint256 targetScaled = (scaledTotalSupplyBefore * factorRay) / WadRayMath.RAY;
      _deficitFactorRay = factorRay;
      _deficitTargetScaled = targetScaled;
      emit DeficitAdjustmentStarted(factorRay, scaledTotalSupplyBefore, targetScaled);
    } else {
      require(committed == factorRay, 'DEFICIT_FACTOR_MISMATCH');
    }

    uint256 index = POOL.getReserveNormalizedIncome(_underlyingAsset);

    // Pass 1: validate the ordering and ADVANCE THE CURSOR BEFORE any external call. `_burn`
    // below calls into the incentives controller, so committing the cursor first means a
    // re-entrant call sees the already-advanced cursor and can only revert. (The controller is
    // not POOL_ADMIN, so re-entry is gated anyway; this makes the guard independent of that.)
    address cursor = _deficitCursor;
    for (uint256 i = 0; i < holders.length; i++) {
      require(holders[i] > cursor, 'DEFICIT_HOLDERS_NOT_ASCENDING');
      cursor = holders[i];
    }
    _deficitCursor = cursor;

    // Pass 2: apply the cut.
    for (uint256 i = 0; i < holders.length; i++) {
      address holder = holders[i];
      uint256 scaledBefore = super.balanceOf(holder);
      // A listed address that holds nothing is a list error. Revert the batch (the cursor write
      // above is rolled back with it) rather than stranding every holder above it.
      require(scaledBefore != 0, 'DEFICIT_NOT_A_HOLDER');

      // factorRay < RAY  =>  scaledBefore * factorRay / RAY < scaledBefore, so the floor is at
      // most scaledBefore - 1 and `cut` is always >= 1.
      uint256 scaledAfter = (scaledBefore * factorRay) / WadRayMath.RAY;
      uint128 cut = (scaledBefore - scaledAfter).toUint128();
      scaledBurned += cut;

      // Mirror of _burnScaled's bookkeeping for a debit of `cutUnderlying`. The interest accrued
      // since the holder's last interaction is emitted now and additionalData is moved to the
      // current index, so the next interaction does not emit it a second time.
      uint256 balanceBefore = _balanceFromScaled(scaledBefore, index);
      uint256 balanceIncrease = balanceBefore -
        _balanceFromScaled(scaledBefore, _userState[holder].additionalData);
      _userState[holder].additionalData = index.toUint128();

      // Updates the holder's scaled balance, _totalSupply and the incentives controller (which
      // must see the OLD balance so accrual up to this point is credited correctly).
      _burn(holder, cut);

      // Amounts are in underlying units, using this token's floor convention (== balanceOf).
      uint256 cutUnderlying = balanceBefore - _balanceFromScaled(scaledAfter, index);
      if (balanceIncrease > cutUnderlying) {
        uint256 amountToMint = balanceIncrease - cutUnderlying;
        emit Transfer(address(0), holder, amountToMint);
        emit Mint(_msgSender(), holder, amountToMint, balanceIncrease, index);
      } else {
        uint256 amountToBurn = cutUnderlying - balanceIncrease;
        emit Transfer(holder, address(0), amountToBurn);
        emit Burn(holder, address(0), amountToBurn, balanceIncrease, index);
      }
      emit DeficitAdjustment(holder, scaledBefore, scaledAfter, factorRay);
    }

    return scaledBurned;
  }

  /**
   * @notice Permanently disables `applyDeficitAdjustment`. Irreversible.
   * @dev Intended to be the last call of the SAME Timelock operation chain that runs the final
   *      batch, so the adjustment can never be left live.
   *
   *      On the DEFICIT_ASSET (ctUSD) proxy, sealing requires
   *        (1) the adjustment to have started (a seal before the first batch would close the
   *            entry point with the deficit unsocialised), and
   *        (2) scaledTotalSupply() <= _deficitTargetScaled, the bound stored by the first batch.
   *      Proof of (2). Let S = scaledTotalSupply at the first batch = sum of every holder's s_i
   *      (the reserve is paused, rates are zero after #36 and accruedToTreasury was minted, so
   *      nothing else moves S), f = factorRay, n = number of holders, T = floor(S*f/RAY).
   *        complete run:   S' = sum floor(s_i*f/RAY) <= floor(sum s_i*f/RAY) = T.       (passes)
   *        holder j skipped: S' >= sum_{i!=j}(s_i*f/RAY - 1) + s_j
   *                             = S*f/RAY + s_j*(1 - f/RAY) - (n-1) > T
   *                          whenever s_j*(1 - f/RAY) > n-1, i.e. whenever the skipped holder's
   *                          CUT exceeds the aggregate rounding slack of n-1 scaled units.  (fails)
   *      With n ~= 2,104 and a ~10% cut, the slack is ~2.1e3 scaled units (~0.002 ctUSD), so a
   *      skipped holder is undetectable by this check only if their balance is below ~2.1e4
   *      scaled units (~0.02 ctUSD). That gap is closed procedurally, not here: the Timelock
   *      operation id binds the exact `holders` calldata of every batch 48 h before execution,
   *      and the committed holder CSV (+ sha256) is what those payloads are built from.
   *
   *      On any OTHER proxy running this implementation (zUSDC.e, zWcBTC), sealing is
   *      unconditional: applyDeficitAdjustment already reverts DEFICIT_WRONG_RESERVE there, and
   *      the seal closes the dormant entry point for good.
   */
  function sealDeficitAdjustment() external virtual onlyPoolAdmin {
    require(!_deficitSealed, 'DEFICIT_ADJUSTMENT_SEALED');
    if (_underlyingAsset == DEFICIT_ASSET) {
      require(_deficitFactorRay != 0, 'DEFICIT_NOT_STARTED');
      require(super.totalSupply() <= _deficitTargetScaled, 'DEFICIT_LIST_INCOMPLETE');
    }
    _deficitSealed = true;
    emit DeficitAdjustmentSealed(
      _deficitFactorRay,
      super.totalSupply(),
      _deficitTargetScaled,
      _deficitCursor
    );
  }

  /**
   * @notice Progress/lifecycle of the one-shot adjustment.
   * @return factorRay The committed surviving fraction (0 if never started)
   * @return cursor The highest holder address adjusted so far
   * @return sealed_ True once the entry point has been permanently disabled
   * @return targetScaled The scaledTotalSupply bound the seal enforces (0 if never started)
   * @return deficitAsset DEFICIT_ASSET — the only underlying whose aToken may be adjusted
   */
  function getDeficitAdjustment()
    external
    view
    virtual
    returns (
      uint256 factorRay,
      address cursor,
      bool sealed_,
      uint256 targetScaled,
      address deficitAsset
    )
  {
    return (_deficitFactorRay, _deficitCursor, _deficitSealed, _deficitTargetScaled, DEFICIT_ASSET);
  }

  /// @inheritdoc IAToken
  function permit(
    address owner,
    address spender,
    uint256 value,
    uint256 deadline,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) external override {
    require(owner != address(0), Errors.ZERO_ADDRESS_NOT_VALID);
    //solium-disable-next-line
    require(block.timestamp <= deadline, Errors.INVALID_EXPIRATION);
    uint256 currentValidNonce = _nonces[owner];
    bytes32 digest = keccak256(
      abi.encodePacked(
        '\x19\x01',
        DOMAIN_SEPARATOR(),
        keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, currentValidNonce, deadline))
      )
    );
    require(owner == ecrecover(digest, v, r, s), Errors.INVALID_SIGNATURE);
    _nonces[owner] = currentValidNonce + 1;
    _approve(owner, spender, value);
  }

  /**
   * @notice Transfers the aTokens between two users. Validates the transfer
   * (ie checks for valid HF after the transfer) if required
   * @param from The source address
   * @param to The destination address
   * @param amount The amount getting transferred
   * @param validate True if the transfer needs to be validated, false otherwise
   */
  function _transfer(address from, address to, uint256 amount, bool validate) internal virtual {
    address underlyingAsset = _underlyingAsset;

    uint256 index = POOL.getReserveNormalizedIncome(underlyingAsset);

    // `super.balanceOf` here is IncentivizedERC20.balanceOf, i.e. the SCALED balance.
    uint256 fromScaledBefore = super.balanceOf(from);
    // A user-initiated (validated) positive transfer from a sender holding zero scaled units
    // must revert: the bounded clamp in ScaledBalanceTokenBase._transfer would otherwise move
    // nothing yet still emit a Transfer and run finalizeTransfer (free collateral-flag enable
    // for the recipient). Only the Pool's transferOnLiquidation (validate == false) may hit
    // the zero-balance clamp; see the note in ScaledBalanceTokenBase._transfer.
    if (validate) {
      require(amount == 0 || fromScaledBefore != 0, Errors.INVALID_BURN_AMOUNT);
    }

    // Balances handed to finalizeTransfer use this token's own convention (floor), matching the
    // public balanceOf. With half-up rayMul, a user transferring exactly balanceOf(self) failed
    // the `balanceFromBefore == amount` equality in SupplyLogic.executeFinalizeTransfer whenever
    // half-up == floor + 1, leaving isUsingAsCollateral set on a zero balance with no way to
    // clear it (setUserUseReserveAsCollateral reverts UNDERLYING_BALANCE_ZERO).
    uint256 fromBalanceBefore = _balanceFromScaled(fromScaledBefore, index);
    uint256 toBalanceBefore = _balanceFromScaled(super.balanceOf(to), index);

    super._transfer(from, to, amount, index);

    if (validate) {
      POOL.finalizeTransfer(underlyingAsset, from, to, amount, fromBalanceBefore, toBalanceBefore);
    }

    emit BalanceTransfer(from, to, amount.rayDiv(index), index);
  }

  /**
   * @notice Overrides the parent _transfer to force validated transfer() and transferFrom()
   * @param from The source address
   * @param to The destination address
   * @param amount The amount getting transferred
   */
  function _transfer(address from, address to, uint128 amount) internal virtual override {
    _transfer(from, to, amount, true);
  }

  /// @inheritdoc ScaledBalanceTokenBase
  /// @dev aTokens mint the supplier's claim rounded DOWN (in favour of the protocol).
  function _scaleForMint(
    uint256 amount,
    uint256 index
  ) internal pure override returns (uint256) {
    return amount.rayDivFloor(index);
  }

  /// @inheritdoc ScaledBalanceTokenBase
  /// @dev aTokens burn the claim rounded UP (withdraw/liquidation, in favour of the protocol).
  function _scaleForBurn(
    uint256 amount,
    uint256 index
  ) internal pure override returns (uint256) {
    return amount.rayDivCeil(index);
  }

  /// @inheritdoc ScaledBalanceTokenBase
  /// @dev aToken balances are rounded DOWN to avoid over-accounting the supplier's claim.
  function _balanceFromScaled(
    uint256 scaledAmount,
    uint256 index
  ) internal pure override returns (uint256) {
    return scaledAmount.rayMulFloor(index);
  }

  /**
   * @dev Overrides the base function to fully implement IAToken
   * @dev see `EIP712Base.DOMAIN_SEPARATOR()` for more detailed documentation
   */
  function DOMAIN_SEPARATOR() public view override(IAToken, EIP712Base) returns (bytes32) {
    return super.DOMAIN_SEPARATOR();
  }

  /**
   * @dev Overrides the base function to fully implement IAToken
   * @dev see `EIP712Base.nonces()` for more detailed documentation
   */
  function nonces(address owner) public view override(IAToken, EIP712Base) returns (uint256) {
    return super.nonces(owner);
  }

  /// @inheritdoc EIP712Base
  function _EIP712BaseId() internal view override returns (string memory) {
    return name();
  }

  /// @inheritdoc IAToken
  function rescueTokens(address token, address to, uint256 amount) external override onlyPoolAdmin {
    require(token != _underlyingAsset, Errors.UNDERLYING_CANNOT_BE_RESCUED);
    IERC20(token).safeTransfer(to, amount);
  }
}

